"""Offline selective header-compression engine (protocol v1.1).

Handles two request modes:
  * replay - control/data-plane audit with exact wire bytes and accounting
  * plan   - exact optimal offline admission planning under node capacities
Any malformed JSON or schema violation yields exactly {"error":"input"}.
"""
import json
import re
import struct
import sys

I64MAX = (1 << 63) - 1


class Bad(Exception):
    """Schema / framing violation."""


ID_RE = re.compile(r"[A-Za-z0-9_.-]{1,32}\Z")
HEX_RE = re.compile(r"(?:[0-9a-f]{2})*\Z")


def _hook(pairs):
    d = {}
    for k, v in pairs:
        if k in d:
            raise Bad()
        d[k] = v
    return d


def _const(_s):
    raise Bad()


def _isint(x):
    return type(x) is int


def _id(s):
    if type(s) is not str or not ID_RE.match(s):
        raise Bad()
    return s


def _hex(s, empty_ok=False):
    if type(s) is not str or not HEX_RE.match(s):
        raise Bad()
    if not empty_ok and not s:
        raise Bad()
    return bytes.fromhex(s)


def _keys(obj, spec):
    if type(obj) is not dict or set(obj) != spec:
        raise Bad()


# ---------------------------------------------------------------- schema ----

FLOW_KEYS_PLAIN = frozenset(("id", "path", "template", "kinds"))
FLOW_KEYS_REPLAY = frozenset(("id", "path", "template", "kinds", "labels"))


def parse_flow(f, mode, caps):
    if type(f) is not dict:
        raise Bad()
    _keys(f, FLOW_KEYS_REPLAY if mode == "replay" else FLOW_KEYS_PLAIN)
    fid = _id(f["id"])
    path = f["path"]
    if type(path) is not list or not (2 <= len(path) <= 9):
        raise Bad()
    nodes = []
    for n in path:
        _id(n)
        if n not in caps:
            raise Bad()
        if n in nodes:
            raise Bad()
        nodes.append(n)
    tmpl = _hex(f["template"])
    H = len(tmpl)
    if not (8 <= H <= 256):
        raise Bad()
    kinds = f["kinds"]
    if type(kinds) is not str or len(kinds) != H:
        raise Bad()
    nq = nt = nk = nd = 0
    kpos = []
    dpos = []
    zpos = []
    qoff = toff = -1
    for i, c in enumerate(kinds):
        if c == "K":
            nk += 1
            kpos.append(i)
        elif c == "D":
            nd += 1
            dpos.append(i)
        elif c == "Z":
            zpos.append(i)
        elif c == "Q":
            nq += 1
            qoff = i
        elif c == "T":
            nt += 1
            toff = i
        else:
            raise Bad()
    if nq != 1 or nt != 1 or nk < 1 or 4 + nd >= H:
        raise Bad()
    N = len(nodes)
    base = bytearray(H)
    for i in kpos:
        base[i] = tmpl[i]
    info = {
        "id": fid,
        "path": nodes,
        "pidx": dict((n, i) for i, n in enumerate(nodes)),
        "N": N,
        "h": N - 1,
        "H": H,
        "tmpl": tmpl,
        "base": base,
        "kpos": kpos,
        "dpos": dpos,
        "zpos": zpos,
        "q": qoff,
        "t": toff,
        "labels": None,
    }
    if mode == "replay":
        labels = f["labels"]
        if type(labels) is not list or len(labels) != N:
            raise Bad()
        for L in labels:
            if not _isint(L) or not (16 <= L <= 1048575):
                raise Bad()
        info["labels"] = list(labels)
    return fid, info


def parse_request(req):
    if type(req) is not dict:
        raise Bad()
    mode = req.get("mode")
    if mode == "replay":
        _keys(req, frozenset(("mode", "capacities", "flows", "events")))
    elif mode == "plan":
        _keys(req, frozenset(("mode", "capacities", "flows", "warmup",
                              "pinned", "offers")))
    else:
        raise Bad()
    caps = req["capacities"]
    if type(caps) is not dict or not (1 <= len(caps) <= 64):
        raise Bad()
    for k, v in caps.items():
        _id(k)
        if not _isint(v) or not (0 <= v <= 512):
            raise Bad()
    flows = req["flows"]
    if type(flows) is not list:
        raise Bad()
    limit = 512 if mode == "replay" else 22
    if not (0 <= len(flows) <= limit):
        raise Bad()
    F = {}
    for f in flows:
        fid, info = parse_flow(f, mode, caps)
        if fid in F:
            raise Bad()
        F[fid] = info
    if mode == "replay":
        events = req["events"]
        if type(events) is not list or not (0 <= len(events) <= 20000):
            raise Bad()
        total_bytes = 0
        evs = []
        for ev in events:
            if type(ev) is not dict:
                raise Bad()
            op = ev.get("op")
            if op == "packet":
                _keys(ev, frozenset(("op", "flow", "header", "payload")))
                fid = _id(ev["flow"])
                if fid not in F:
                    raise Bad()
                hdr = _hex(ev["header"])
                if len(hdr) != F[fid]["H"]:
                    raise Bad()
                pay = _hex(ev["payload"], True)
                if len(pay) > 2048:
                    raise Bad()
                total_bytes += len(hdr) + len(pay)
                if total_bytes > (2 << 20):
                    raise Bad()
                evs.append(("packet", fid, hdr, pay))
            elif op == "put":
                _keys(ev, frozenset(("op", "flow", "node")))
                fid = _id(ev["flow"])
                node = _id(ev["node"])
                if fid not in F:
                    raise Bad()
                if node not in F[fid]["pidx"]:
                    raise Bad()
                evs.append(("put", fid, node))
            elif op in ("enable", "disable"):
                _keys(ev, frozenset(("op", "flow")))
                fid = _id(ev["flow"])
                if fid not in F:
                    raise Bad()
                evs.append((op, fid))
            elif op == "reset":
                _keys(ev, frozenset(("op",)))
                evs.append(("reset",))
            else:
                raise Bad()
        return {"mode": "replay", "caps": caps, "flows": F, "events": evs}
    warmup = req["warmup"]
    if not _isint(warmup) or not (0 <= warmup <= 1000000000):
        raise Bad()
    pinned = req["pinned"]
    if type(pinned) is not list:
        raise Bad()
    pin = []
    for p in pinned:
        _id(p)
        if p not in F:
            raise Bad()
        if p in pin:
            raise Bad()
        pin.append(p)
    offers = req["offers"]
    if type(offers) is not dict or set(offers) != set(F):
        raise Bad()
    hdr_bytes = 0
    runs = {}
    for fid, lst in offers.items():
        if type(lst) is not list or not (0 <= len(lst) <= 256):
            raise Bad()
        H = F[fid]["H"]
        seq = []
        tot = 0
        for r in lst:
            if type(r) is not dict:
                raise Bad()
            _keys(r, frozenset(("header", "count")))
            hdr = _hex(r["header"])
            if len(hdr) != H:
                raise Bad()
            cnt = r["count"]
            if not _isint(cnt) or not (1 <= cnt <= 1000000000):
                raise Bad()
            hdr_bytes += len(hdr)
            if hdr_bytes > 65536:
                raise Bad()
            tot += cnt
            if tot > 1000000000:
                raise Bad()
            seq.append((hdr, cnt))
        runs[fid] = seq
    return {"mode": "plan", "caps": caps, "flows": F, "warmup": warmup,
            "pinned": pin, "runs": runs}


# ---------------------------------------------------------------- replay ----

_U32 = struct.Struct(">I").pack


def _mpls_packet(fi, hdr, pay, out):
    labels = fi["labels"]
    N = fi["N"]
    q = hdr[fi["q"]]
    ttl = hdr[fi["t"]]
    dpos = fi["dpos"]
    residue = bytes([hdr[i] for i in dpos])
    mid = residue + pay
    wire = out["wire"]
    emitted = 0
    t = ttl
    for i in range(N):
        if t <= 0:
            break
        word = (labels[i] << 12) | (q << 9) | 0x100 | t
        wire.append((_U32(word) + mid).hex())
        emitted += 1
        if i < N - 1:
            if t <= 1:
                break
            t -= 1
    out["byte_hops"] = sum(len(s) >> 1 for s in wire)
    if emitted == N:
        vec = bytearray(fi["base"])
        for j, i in enumerate(dpos):
            vec[i] = residue[j]
        vec[fi["q"]] = q
        vec[fi["t"]] = t
        out["delivered"] = (bytes(vec) + pay).hex()
    else:
        out["delivered"] = None
    return out


def _ip_packet(fi, hdr, pay, out, reason):
    N = fi["N"]
    off = fi["t"]
    ttl = hdr[off]
    body = bytearray(hdr)
    wire = out["wire"]
    emitted = 0
    t = ttl
    for i in range(N):
        if t <= 0:
            break
        body[off] = t
        wire.append((bytes(body) + pay).hex())
        emitted += 1
        if i < N - 1:
            if t <= 1:
                break
            t -= 1
    out["byte_hops"] = sum(len(s) >> 1 for s in wire)
    out["delivered"] = wire[-1] if emitted == N else None
    return out


def run_replay(R):
    caps = R["caps"]
    F = R["flows"]
    tables = dict((n, {}) for n in caps)
    enabled = set()
    results = []
    for ev in R["events"]:
        op = ev[0]
        if op == "packet":
            _, fid, hdr, pay = ev
            fi = F[fid]
            out = {"mode": None, "reason": None, "wire": [],
                   "delivered": None, "byte_hops": 0}
            if fid not in enabled:
                out["mode"], out["reason"] = "ip", "disabled"
                _ip_packet(fi, hdr, pay, out, None)
            else:
                bad = False
                tmpl = fi["tmpl"]
                for i in fi["kpos"]:
                    if hdr[i] != tmpl[i]:
                        bad = True
                        break
                if bad:
                    out["mode"], out["reason"] = "ip", "mismatch"
                    _ip_packet(fi, hdr, pay, out, None)
                elif hdr[fi["q"]] > 7:
                    out["mode"], out["reason"] = "ip", "qos"
                    _ip_packet(fi, hdr, pay, out, None)
                else:
                    out["mode"], out["reason"] = "mpls", "compressed"
                    _mpls_packet(fi, hdr, pay, out)
            results.append(out)
        elif op == "put":
            _, fid, node = ev
            fi = F[fid]
            tb = tables[node]
            label = fi["labels"][fi["pidx"][node]]
            cur = tb.get(label)
            if cur == fid:
                st = "ok"
            elif cur is not None and cur in enabled:
                st = "busy"
            elif label not in tb and len(tb) >= caps[node]:
                st = "full"
            else:
                tb[label] = fid
                st = "ok"
            results.append({"status": st})
        elif op == "enable":
            fid = ev[1]
            if fid in enabled:
                results.append({"status": "ok"})
                continue
            fi = F[fid]
            ready = True
            for i, node in enumerate(fi["path"]):
                if tables[node].get(fi["labels"][i]) != fid:
                    ready = False
                    break
            if ready:
                enabled.add(fid)
                results.append({"status": "ok"})
            else:
                results.append({"status": "unready"})
        elif op == "disable":
            enabled.discard(ev[1])
            results.append({"status": "ok"})
        else:  # reset
            enabled.clear()
            results.append({"status": "ok"})
    tables_out = []
    for node in sorted(tables):
        tb = tables[node]
        for label in sorted(tb):
            tables_out.append({"node": node, "label": label,
                               "flow": tb[label]})
    return {"results": results, "active": sorted(enabled),
            "tables": tables_out}


# ----------------------------------------------------------------- plan -----

def flow_benefit(fi, seq, warmup):
    """Eligible-packet header savings for one flow."""
    N, h, H = fi["N"], fi["h"], fi["H"]
    per = (H - 4 - len(fi["dpos"])) * N
    tmpl = fi["tmpl"]
    kpos = fi["kpos"]
    qoff, toff = fi["q"], fi["t"]
    left = warmup
    total = 0
    for hdr, cnt in seq:
        if left:
            if left >= cnt:
                left -= cnt
                continue
            left = 0
        ok = hdr[qoff] <= 7 and hdr[toff] > h
        if ok:
            for i in kpos:
                if hdr[i] != tmpl[i]:
                    ok = False
                    break
        if ok:
            total += per * cnt
    return total


def solve_plan(R):
    caps = R["caps"]
    F = R["flows"]
    warmup = R["warmup"]
    ben = {}
    for fid, seq in R["runs"].items():
        ben[fid] = flow_benefit(F[fid], seq, warmup)
    # pinned flows are mandatory
    used = dict((n, 0) for n in caps)
    forced = []
    for fid in R["pinned"]:
        for n in F[fid]["path"]:
            used[n] += 1
        forced.append(fid)
    for n, c in used.items():
        if c > caps[n]:
            return {"infeasible": True}
    avail = dict((n, caps[n] - used[n]) for n in caps)
    # candidates: positive benefit, not pinned
    items = []
    for fid in sorted(F):
        if fid in R["pinned"] or ben[fid] <= 0:
            continue
        items.append((fid, ben[fid], list(F[fid]["path"])))
    # iteratively drop items that cannot fit anywhere (avail == 0)
    changed = True
    while changed:
        changed = False
        keep = []
        for it in items:
            if any(avail[n] <= 0 for n in it[2]):
                changed = True
                continue
            keep.append(it)
        items = keep
    if not items:
        return _finish(forced, [], ben)
    # binding nodes only
    cnt_per_node = {}
    for fid, b, path in items:
        for n in path:
            cnt_per_node[n] = cnt_per_node.get(n, 0) + 1
    binding = [n for n, c in cnt_per_node.items() if c > avail[n]]
    if not binding:
        return _finish(forced, [it[0] for it in items], ben)
    bind_index = dict((n, i) for i, n in enumerate(sorted(binding)))
    m = len(binding)
    cap_left = [avail[n] for n in sorted(binding)]
    # group identical (nodeset, benefit) items
    groups = {}
    for fid, b, path in items:
        nodes = sorted(set(bind_index[n] for n in path if n in bind_index))
        key = (tuple(nodes), b)
        groups.setdefault(key, []).append(fid)
    gl = []
    for (nodes, b), fids in groups.items():
        nodes = list(nodes)
        if not nodes:
            gl.append((b, (), len(fids), fids))
        else:
            gl.append((b, tuple(nodes), len(fids), fids))
    gl.sort(key=lambda g: (-g[0], len(g[1])))
    G = len(gl)
    suff_val = [0] * (G + 1)
    suff_cnt = [0] * (G + 1)
    suff_use = [[0] * m for _ in range(G + 1)]
    for i in range(G - 1, -1, -1):
        b, nodes, k, _f = gl[i]
        suff_val[i] = suff_val[i + 1] + b * k
        suff_cnt[i] = suff_cnt[i + 1] + k
        prev = suff_use[i + 1]
        cur = suff_use[i] = list(prev)
        for n in nodes:
            cur[n] += k
    best = [0, 0]  # value, count
    seen = {}

    def dfs(i, val, cnt, left):
        if val > best[0] or (val == best[0] and cnt < best[1]):
            best[0], best[1] = val, cnt
        if i >= G:
            return
        if val + suff_val[i] < best[0]:
            return
        if val + suff_val[i] == best[0] and cnt >= best[1]:
            return
        # all remaining items fit -> take everything
        su = suff_use[i]
        fits = True
        for n in range(m):
            if su[n] > left[n]:
                fits = False
                break
        if fits:
            v = val + suff_val[i]
            c = cnt + suff_cnt[i]
            if v > best[0] or (v == best[0] and c < best[1]):
                best[0], best[1] = v, c
            return
        key = (i, tuple(left))
        prev = seen.get(key)
        if prev is not None:
            pv, pc = prev
            if pv >= val and pc <= cnt:
                return
            seen[key] = (val, cnt)
        else:
            seen[key] = (val, cnt)
        b, nodes, k, _f = gl[i]
        jm = k
        for n in nodes:
            if left[n] < jm:
                jm = left[n]
        for j in range(jm, 0, -1):
            if val + j * b + suff_val[i + 1] < best[0]:
                break
            nl = list(left)
            for n in nodes:
                nl[n] -= j
            dfs(i + 1, val + j * b, cnt + j, nl)
        dfs(i + 1, val, cnt, left)

    sys.setrecursionlimit(10000)
    dfs(0, 0, 0, cap_left)
    # recover a selected set matching the optimum
    chosen = recover(gl, cap_left, best[0], best[1])
    return _finish(forced, chosen, ben)


def recover(gl, cap_left, target_val, target_cnt):
    m = len(cap_left)
    G = len(gl)
    suff_val = [0] * (G + 1)
    for i in range(G - 1, -1, -1):
        b, nodes, k, _f = gl[i]
        suff_val[i] = suff_val[i + 1] + b * k
    left = list(cap_left)
    out = []
    need_v, need_c = target_val, target_cnt
    for i in range(G):
        b, nodes, k, fids = gl[i]
        jm = min(k, need_c)
        for n in nodes:
            jm = min(jm, left[n])
        done = False
        for j in range(jm, -1, -1):
            if j * b + suff_val[i + 1] < need_v:
                continue
            nl = list(left)
            for n in nodes:
                nl[n] -= j
            if _feas_rest(gl, nl, i + 1, need_v - j * b):
                out.extend(fids[:j])
                left = nl
                need_v -= j * b
                need_c -= j
                done = True
                break
        if not done:  # should not happen
            return out
        if need_c == 0:
            break
    return out


def _feas_rest(gl, left, i, need_v):
    """Greedy check: can remaining groups still deliver need_v value?"""
    G = len(gl)
    got = 0
    for j in range(i, G):
        b, nodes, k, _f = gl[j]
        jm = k
        for n in nodes:
            if left[n] < jm:
                jm = left[n]
        for _ in range(jm):
            got += b
            if got >= need_v:
                return True
    return got >= need_v


def _finish(forced, chosen, ben):
    sel = sorted(set(forced) | set(chosen))
    saved = 0
    for fid in sel:
        saved += ben[fid]
    if saved > I64MAX or saved < -(I64MAX + 1):
        raise Bad()
    return {"selected": sel, "saved": saved}


# ----------------------------------------------------------------- main -----

def respond(req):
    R = parse_request(req)
    if R["mode"] == "replay":
        return run_replay(R)
    return solve_plan(R)


def main():
    out = sys.stdout
    data = sys.stdin.buffer.read()
    for raw in data.split(b"\n"):
        if not raw.strip():
            if raw == b"" :
                continue
            out.write('{"error":"input"}\n')
            continue
        if len(raw) > 16 * 1024 * 1024:
            out.write('{"error":"input"}\n')
            out.flush()
            continue
        try:
            obj = json.loads(raw.decode("utf-8"), object_pairs_hook=_hook,
                             parse_constant=_const)
        except Exception:
            out.write('{"error":"input"}\n')
            out.flush()
            continue
        try:
            resp = respond(obj)
        except Bad:
            resp = {"error": "input"}
        except (KeyError, TypeError, ValueError, IndexError, OverflowError):
            resp = {"error": "input"}
        out.write(json.dumps(resp, separators=(",", ":")))
        out.write("\n")
        out.flush()
    out.flush()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
